package io.invenlio.receiving;
import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.testcontainers.service.connection.ServiceConnection;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import org.testcontainers.junit.jupiter.*;import org.testcontainers.postgresql.PostgreSQLContainer;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@Testcontainers@SpringBootTest@AutoConfigureMockMvc@ActiveProfiles("test")class ReceivingIntegrationTest{@Container@ServiceConnection static final PostgreSQLContainer DB=new PostgreSQLContainer("postgres:17.6-alpine");@Autowired JdbcTemplate db;@Autowired MockMvc mvc;static final UUID T=UUID.randomUUID(),PO=UUID.randomUUID(),POL=UUID.randomUUID(),S=UUID.randomUUID(),W=UUID.randomUUID(),REC=UUID.randomUUID(),BIN=UUID.randomUUID(),V=UUID.randomUUID();
 @BeforeEach void seed(){db.execute("TRUNCATE organizations,user_identities CASCADE");UUID user=UUID.randomUUID(),membership=UUID.randomUUID(),role=UUID.randomUUID(),zone=UUID.randomUUID(),product=UUID.randomUUID(),sp=UUID.randomUUID();db.update("INSERT INTO organizations(id,name,slug,status,default_locale,default_timezone,default_currency,created_at,updated_at,version)VALUES(?,?,?,'ACTIVE','en','UTC','EUR',now(),now(),0)",T,"Receiving Tenant","receiving-tenant");db.update("INSERT INTO user_identities(id,keycloak_subject,status,created_at,updated_at)VALUES(?,?,'ACTIVE',now(),now())",user,"receiver");db.update("INSERT INTO organization_memberships(id,tenant_id,user_identity_id,status,created_at,updated_at,version)VALUES(?,?,?,'ACTIVE',now(),now(),0)",membership,T,user);db.update("INSERT INTO roles(id,tenant_id,name,system_role,created_at,updated_at,version)VALUES(?,?,?,false,now(),now(),0)",role,T,"RECEIVER");for(String p:List.of("receiving:read","receiving:manage","put-away:read","put-away:manage"))db.update("INSERT INTO role_permissions VALUES(?,?,?)",T,role,p);db.update("INSERT INTO membership_roles VALUES(?,?,?)",T,membership,role);db.update("INSERT INTO suppliers(id,tenant_id,supplier_number,normalized_supplier_number,name,status,default_currency,created_at,updated_at,version)VALUES(?,?,'SUP','SUP','Supplier','ACTIVE','EUR',now(),now(),0)",S,T);db.update("INSERT INTO warehouses(id,tenant_id,code,normalized_code,name,status,timezone,created_at,updated_at,version)VALUES(?,?,'WH','WH','Warehouse','ACTIVE','UTC',now(),now(),0)",W,T);db.update("INSERT INTO warehouse_zones(id,tenant_id,warehouse_id,code,normalized_code,name,type,status,sequence,created_at,updated_at,version)VALUES(?,?,?,'Z','Z','Zone','STORAGE','ACTIVE',0,now(),now(),0)",zone,T,W);location(REC,zone,"REC","RECEIVING");location(BIN,zone,"BIN","BIN");db.update("INSERT INTO catalog_products(id,tenant_id,name,status,base_unit,created_at,updated_at,version)VALUES(?,?,?,'ACTIVE','EA',now(),now(),0)",product,T,"Widget");db.update("INSERT INTO catalog_product_variants(id,tenant_id,product_id,sku,normalized_sku,status,display_name,base_unit,option_signature,tracking_mode,created_at,updated_at,version)VALUES(?,?,?,?,?,'ACTIVE','Widget','EA','DEFAULT','NONE',now(),now(),0)",V,T,product,"SKU","SKU");db.update("INSERT INTO supplier_products(id,tenant_id,supplier_id,variant_id,supplier_sku,normalized_supplier_sku,purchase_unit_code,base_units_per_purchase_unit,unit_cost,currency,active,preferred,created_at,updated_at,version)VALUES(?,?,?,?,?,?,'EA',1,1,'EUR',true,false,now(),now(),0)",sp,T,S,V,"SKU","SKU");db.update("INSERT INTO purchase_orders(id,tenant_id,supplier_id,warehouse_id,purchase_order_number,status,supplier_number_snapshot,supplier_name_snapshot,warehouse_code_snapshot,warehouse_name_snapshot,currency,subtotal,total,created_by,created_at,updated_at,version)VALUES(?,?,?,?,?,'SENT','SUP','Supplier','WH','Warehouse','EUR',100,100,?,now(),now(),0)",PO,T,S,W,"PO-TEST",user);db.update("INSERT INTO purchase_order_lines(id,tenant_id,purchase_order_id,supplier_id,supplier_product_id,variant_id,line_number,supplier_sku_snapshot,variant_sku_snapshot,description_snapshot,ordered_quantity,purchase_unit_code,base_units_per_purchase_unit,base_quantity,unit_cost,currency,line_subtotal,created_at,updated_at,version)VALUES(?,?,?,?,?,?,1,'SKU','SKU','Widget',100,'EA',1,100,1,'EUR',100,now(),now(),0)",POL,T,PO,S,sp,V);}
 @Test void mandatoryPartialReceiptAndPutAwayReconcilesLedger()throws Exception{UUID r1=receipt("60",REC);postReceipt(r1,"r1",0).andExpect(jsonPath("$.status").value("POSTED"));assertEquals("PARTIALLY_RECEIVED",poStatus());assertBalance(REC,"60.000000");UUID l1=receiptLine(r1);UUID p1=task(l1,BIN,"60");complete(p1,"p1",0).andExpect(status().isOk());assertBalance(REC,"0.000000");assertBalance(BIN,"60.000000");UUID r2=receipt("40",REC);postReceipt(r2,"r2",0).andExpect(status().isOk());assertEquals("RECEIVED",poStatus());UUID p2=task(receiptLine(r2),BIN,"40");complete(p2,"p2",0);assertBalance(REC,"0.000000");assertBalance(BIN,"100.000000");assertEquals(0,db.queryForObject("SELECT count(*) FROM inventory_balances b WHERE b.on_hand_quantity<>(SELECT COALESCE(sum(e.quantity_delta),0) FROM inventory_ledger_entries e WHERE e.tenant_id=b.tenant_id AND e.variant_id=b.variant_id AND e.warehouse_id=b.warehouse_id AND e.location_id=b.location_id AND e.lot_id IS NOT DISTINCT FROM b.lot_id AND e.serial_id IS NOT DISTINCT FROM b.serial_id)",Integer.class));assertEquals(6,db.queryForObject("SELECT count(*) FROM inventory_ledger_entries",Integer.class));}
 @Test void concurrentReceiptsCannotOverReceive()throws Exception{UUID a=receipt("100",REC),b=receipt("100",REC);Set<Integer> result=race(()->postReceipt(a,"a",0).andReturn().getResponse().getStatus(),()->postReceipt(b,"b",0).andReturn().getResponse().getStatus());assertTrue(result.contains(200));assertEquals(1,result.stream().filter(x->x!=200).count());assertEquals(0,new java.math.BigDecimal("100").compareTo(db.queryForObject("SELECT received_base_quantity FROM purchase_order_lines WHERE id=?",java.math.BigDecimal.class,POL)));assertBalance(REC,"100.000000");}
 @Test void concurrentSameIdempotencyKeyHasOnePhysicalEffect()throws Exception{UUID r=receipt("100",REC);Set<Integer> result=race(()->postReceipt(r,"same-key",0).andReturn().getResponse().getStatus(),()->postReceipt(r,"same-key",0).andReturn().getResponse().getStatus());assertEquals(Set.of(200),result);assertEquals(1,db.queryForObject("SELECT count(*) FROM inventory_movements WHERE movement_type='GOODS_RECEIPT'",Integer.class));assertBalance(REC,"100.000000");}
 @Test void receivingLocationTenantAndPermissionRulesAreEnforced()throws Exception{mvc.perform(post("/api/v1/goods-receipts").with(token()).contentType("application/json").content(body("1",BIN))).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("RECEIVING_LOCATION_REQUIRED"));mvc.perform(get("/api/v1/goods-receipts")).andExpect(status().isUnauthorized());db.update("DELETE FROM role_permissions WHERE tenant_id=? AND permission_key='receiving:manage'",T);mvc.perform(post("/api/v1/goods-receipts").with(token()).contentType("application/json").content(body("1",REC))).andExpect(status().isForbidden());mvc.perform(get("/api/v1/goods-receipts/"+UUID.randomUUID()).with(token())).andExpect(status().isNotFound());}
 @Test void concurrentPutAwayAllocationCannotExceedReceiptLine()throws Exception{UUID r=receipt("100",REC);postReceipt(r,"posted",0);UUID line=receiptLine(r);Set<Integer> result=race(()->taskStatus(line,"60"),()->taskStatus(line,"60"));assertTrue(result.contains(200));assertEquals(1,result.stream().filter(x->x!=200).count());assertEquals(0,new java.math.BigDecimal("60").compareTo(db.queryForObject("SELECT sum(quantity) FROM put_away_tasks",java.math.BigDecimal.class)));}
 @Test void serializedStockRelocatesWithoutDuplication()throws Exception{db.update("UPDATE catalog_product_variants SET tracking_mode='SERIAL' WHERE id=?",V);UUID serial=UUID.randomUUID();db.update("INSERT INTO inventory_serials(id,tenant_id,variant_id,serial_number,normalized_serial_number,status,created_at,updated_at,version)VALUES(?,?,?,'SER-1','SER-1','ACTIVE',now(),now(),0)",serial,T,V);String json="{\"purchaseOrderId\":\""+PO+"\",\"lines\":[{\"purchaseOrderLineId\":\""+POL+"\",\"receivedBaseQuantity\":\"1\",\"receivingLocationId\":\""+REC+"\",\"serialId\":\""+serial+"\"}]}";UUID receipt=id(mvc.perform(post("/api/v1/goods-receipts").with(token()).contentType("application/json").content(json)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());postReceipt(receipt,"serial-receipt",0).andExpect(status().isOk());UUID putaway=task(receiptLine(receipt),BIN,"1");complete(putaway,"serial-putaway",0).andExpect(status().isOk());assertEquals(0,db.queryForObject("SELECT count(*) FROM inventory_balances WHERE serial_id=? AND location_id=? AND on_hand_quantity>0",Integer.class,serial,REC));assertEquals(1,db.queryForObject("SELECT count(*) FROM inventory_balances WHERE serial_id=? AND location_id=? AND on_hand_quantity=1",Integer.class,serial,BIN));}
 @Test void serialRemainsTraceableFromReceiptThroughShipment()throws Exception{
  UUID role=db.queryForObject("SELECT id FROM roles WHERE tenant_id=? AND name='RECEIVER'",UUID.class,T);
  for(String permission:List.of("customer:read","customer:manage","sales-order:read","sales-order:manage","sales-order:allocate","picking:read","picking:manage","packing:read","packing:manage","shipping:read","shipping:manage","shipping:dispatch"))db.update("INSERT INTO role_permissions VALUES(?,?,?)",T,role,permission);
  db.update("UPDATE catalog_product_variants SET tracking_mode='SERIAL' WHERE id=?",V);
  UUID serial=UUID.randomUUID(),packing=UUID.randomUUID();
  db.update("INSERT INTO inventory_serials(id,tenant_id,variant_id,serial_number,normalized_serial_number,status,created_at,updated_at,version)VALUES(?,?,?,'SER-TRACE','SER-TRACE','ACTIVE',now(),now(),0)",serial,T,V);
  UUID zone=db.queryForObject("SELECT id FROM warehouse_zones WHERE warehouse_id=?",UUID.class,W);location(packing,zone,"PACK","PACKING");
  String receivingBody="{\"purchaseOrderId\":\""+PO+"\",\"lines\":[{\"purchaseOrderLineId\":\""+POL+"\",\"receivedBaseQuantity\":\"1\",\"receivingLocationId\":\""+REC+"\",\"serialId\":\""+serial+"\"}]}";
  UUID receipt=id(mvc.perform(post("/api/v1/goods-receipts").with(token()).contentType("application/json").content(receivingBody)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());
  postReceipt(receipt,"serial-trace-receipt",0).andExpect(status().isOk());complete(task(receiptLine(receipt),BIN,"1"),"serial-trace-putaway",0).andExpect(status().isOk());
  UUID customer=id(mvc.perform(post("/api/v1/customers").with(token()).contentType("application/json").content("{\"name\":\"Trace Customer\",\"currency\":\"EUR\",\"shippingAddress\":\"Main Street 1\",\"version\":0}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());
  mvc.perform(post("/api/v1/customers/"+customer+"/activate").with(token()).contentType("application/json").content("{\"version\":0}")).andExpect(status().isOk());
  UUID order=id(mvc.perform(post("/api/v1/sales-orders").with(token()).contentType("application/json").content("{\"customerId\":\""+customer+"\",\"warehouseId\":\""+W+"\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());
  mvc.perform(post("/api/v1/sales-orders/"+order+"/lines").with(token()).contentType("application/json").content("{\"variantId\":\""+V+"\",\"quantity\":\"1\",\"unitPrice\":\"10\"}")).andExpect(status().isOk());
  mvc.perform(post("/api/v1/sales-orders/"+order+"/confirm").with(token()).contentType("application/json").content("{\"version\":1}")).andExpect(status().isOk());
  mvc.perform(post("/api/v1/sales-orders/"+order+"/allocate").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("ALLOCATED"));
  assertEquals(serial,db.queryForObject("SELECT x.serial_id FROM sales_allocations a JOIN inventory_reservation_allocations x ON x.reservation_id=a.inventory_reservation_id WHERE a.sales_order_id=?",UUID.class,order));
  UUID pick=id(mvc.perform(post("/api/v1/pick-lists").with(token()).contentType("application/json").content("{\"salesOrderId\":\""+order+"\",\"packingLocationId\":\""+packing+"\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());
  mvc.perform(post("/api/v1/pick-lists/"+pick+"/start").with(token()).contentType("application/json").content("{\"version\":0}")).andExpect(status().isOk());
  UUID pickTask=db.queryForObject("SELECT id FROM pick_tasks WHERE pick_list_id=?",UUID.class,pick);
  mvc.perform(post("/api/v1/pick-lists/"+pick+"/tasks/"+pickTask+"/complete").with(token()).header("Idempotency-Key","serial-trace-pick").contentType("application/json").content("{\"version\":0}")).andExpect(status().isOk());
  UUID session=id(mvc.perform(post("/api/v1/packing-sessions").with(token()).contentType("application/json").content("{\"pickListId\":\""+pick+"\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());
  UUID pkg=id(mvc.perform(post("/api/v1/packing-sessions/"+session+"/packages").with(token()).contentType("application/json").content("{}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());
  mvc.perform(post("/api/v1/packing-sessions/"+session+"/packages/"+pkg+"/items").with(token()).contentType("application/json").content("{\"pickTaskId\":\""+pickTask+"\",\"quantity\":\"1\"}")).andExpect(status().isOk());
  mvc.perform(post("/api/v1/packing-sessions/"+session+"/packages/"+pkg+"/complete").with(token()).contentType("application/json").content("{\"version\":0}")).andExpect(status().isOk());
  mvc.perform(post("/api/v1/packing-sessions/"+session+"/complete").with(token()).contentType("application/json").content("{\"version\":0}")).andExpect(status().isOk());
  UUID shipment=id(mvc.perform(post("/api/v1/shipments").with(token()).contentType("application/json").content("{\"salesOrderId\":\""+order+"\",\"packageIds\":[\""+pkg+"\"]}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());
  mvc.perform(post("/api/v1/shipments/"+shipment+"/dispatch").with(token()).header("Idempotency-Key","serial-trace-dispatch")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("DISPATCHED"));
  mvc.perform(get("/api/v1/sales-orders/"+order).with(token())).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("COMPLETED"));
  assertEquals(0,db.queryForObject("SELECT count(*) FROM inventory_balances WHERE serial_id=? AND on_hand_quantity>0",Integer.class,serial));
  assertTrue(db.queryForObject("SELECT count(*) FROM inventory_ledger_entries WHERE serial_id=?",Integer.class,serial)>=4);
 }
 private void location(UUID id,UUID z,String code,String type){db.update("INSERT INTO warehouse_locations(id,tenant_id,warehouse_id,zone_id,code,normalized_code,name,type,status,sequence,scan_code,normalized_scan_code,created_at,updated_at,version)VALUES(?,?,?,?,?,?,?,?,'ACTIVE',0,?,?,now(),now(),0)",id,T,W,z,code,code,code,type,code,code);}private UUID receipt(String q,UUID loc)throws Exception{return id(mvc.perform(post("/api/v1/goods-receipts").with(token()).contentType("application/json").content(body(q,loc))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());}private String body(String q,UUID loc){return "{\"purchaseOrderId\":\""+PO+"\",\"lines\":[{\"purchaseOrderLineId\":\""+POL+"\",\"receivedBaseQuantity\":\""+q+"\",\"receivingLocationId\":\""+loc+"\"}]}";}private org.springframework.test.web.servlet.ResultActions postReceipt(UUID id,String key,long v)throws Exception{return mvc.perform(post("/api/v1/goods-receipts/"+id+"/post").with(token()).header("Idempotency-Key",key).contentType("application/json").content("{\"version\":"+v+"}"));}private UUID task(UUID line,UUID dest,String q)throws Exception{return id(mvc.perform(post("/api/v1/put-away-tasks").with(token()).contentType("application/json").content("{\"receiptLineId\":\""+line+"\",\"destinationLocationId\":\""+dest+"\",\"quantity\":\""+q+"\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());}private int taskStatus(UUID line,String q)throws Exception{return mvc.perform(post("/api/v1/put-away-tasks").with(token()).contentType("application/json").content("{\"receiptLineId\":\""+line+"\",\"destinationLocationId\":\""+BIN+"\",\"quantity\":\""+q+"\"}")).andReturn().getResponse().getStatus();}private org.springframework.test.web.servlet.ResultActions complete(UUID id,String key,long v)throws Exception{return mvc.perform(post("/api/v1/put-away-tasks/"+id+"/complete").with(token()).header("Idempotency-Key",key).contentType("application/json").content("{\"version\":"+v+"}"));}private UUID receiptLine(UUID r){return db.queryForObject("SELECT id FROM goods_receipt_lines WHERE goods_receipt_id=?",UUID.class,r);}private String poStatus(){return db.queryForObject("SELECT status FROM purchase_orders WHERE id=?",String.class,PO);}private void assertBalance(UUID loc,String expected){assertEquals(0,new java.math.BigDecimal(expected).compareTo(db.queryForObject("SELECT on_hand_quantity FROM inventory_balances WHERE tenant_id=? AND variant_id=? AND location_id=?",java.math.BigDecimal.class,T,V,loc)));}private UUID id(String json){return UUID.fromString(json.replaceFirst(".*?\"id\":\"([^\"]+)\".*","$1"));}private org.springframework.test.web.servlet.request.RequestPostProcessor token(){return jwt().jwt(j->j.subject("receiver").claim("tenant_id",T.toString()));}private Set<Integer>race(Callable<Integer>a,Callable<Integer>b)throws Exception{ExecutorService p=Executors.newFixedThreadPool(2);try{CountDownLatch go=new CountDownLatch(1);Future<Integer>x=p.submit(()->{go.await();return a.call();}),y=p.submit(()->{go.await();return b.call();});go.countDown();return new HashSet<>(List.of(x.get(),y.get()));}finally{p.shutdownNow();}}
}
